<script setup lang="ts">
import { Search,FolderOpen,CalendarDays,Bell,BookOpen,FilePlus2, Headset, RefreshCw, Clock3, CheckCircle2, AlertCircle } from 'lucide-vue-next'
import type { Application,ApplicationStatus } from '~/types/models'
import { normalizeSearch } from '~/utils/search'
definePageMeta({title:'Tổng quan'})
const {data:cases,error:casesError,refresh:refreshCases}=await useFetch<Application[]>('/api/applications', {key:'staff-applications'})
const {data:auth}=await useFetch<{authenticated:boolean;name?:string;role?:string}>('/api/auth/me', {key:'staff-auth-home'})
const {date}=useFormat();const search=ref('');const status=ref('')
const total=computed(()=>cases.value?.length||0)
const submitted=computed(()=>cases.value?.filter(c=>c.status==='submitted').length||0)
const processing=computed(()=>cases.value?.filter(c=>c.status==='processing').length||0)
const completed=computed(()=>cases.value?.filter(c=>c.status==='completed').length||0)
const supplement=computed(()=>cases.value?.filter(c=>c.status==='supplement').length||0)
const overdue=computed(()=>cases.value?.filter(c=>c.due_at&&new Date(c.due_at)<new Date()&&['submitted','processing','supplement'].includes(c.status)).length||0)
const filtered=computed(()=>cases.value?.filter(c=>(!status.value||c.status===status.value)&&normalizeSearch(`${c.id} ${c.procedure_title} ${c.applicant_name}`).includes(normalizeSearch(search.value)))||[])
</script>
<template><div class="space-y-4"><div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="text-xl font-extrabold">Chào mừng{{auth?.authenticated?', '+auth.name:''}}, cán bộ quản lý! 👋</h2><p class="mt-1 text-sm text-muted">Theo dõi tình trạng hồ sơ, duyệt và giải quyết đơn từ công dân tại đây.</p></div><div class="flex items-center gap-2 text-xs text-muted"><CalendarDays :size="16"/>Thông tin mô phỏng · 2026</div></div>
 <div class="grid grid-cols-2 gap-3 lg:grid-cols-6"><MetricCard label="Tổng hồ sơ" :value="total" icon="files" tone="blue"/><MetricCard label="Đã tiếp nhận" :value="submitted" icon="clock" tone="blue"/><MetricCard label="Đang xử lý" :value="processing" icon="clock" tone="orange"/><MetricCard label="Cần bổ sung" :value="supplement" icon="alert" tone="purple"/><MetricCard label="Hoàn thành" :value="completed" icon="check" tone="green"/><MetricCard label="Quá hạn" :value="overdue" icon="alert" tone="red"/></div>
 <div class="grid gap-3 lg:grid-cols-2"><section class="panel p-4"><div class="mb-3 flex flex-wrap items-center justify-between gap-2"><h3 class="section-label !mb-0">📋 Hồ sơ cần xử lý ngay</h3><NuxtLink to="/ho-so" class="text-xs font-bold text-brand-600 hover:underline">Xem tất cả hồ sơ <ArrowRight :size="14" class="inline"/></NuxtLink></div><div v-if="casesError" class="panel p-5 text-sm text-rose-700">Không tải được danh sách. Kiểm tra PostgreSQL và phiên đăng nhập. <button class="ml-1 font-bold underline" @click="refreshCases()">Thử lại</button>.</div><div v-else-if="!filtered.filter(c=>['submitted','processing','supplement'].includes(c.status)).length" class="panel p-8 text-center text-muted">Không có hồ sơ cần xử lý.</div><div v-else class="grid gap-3 lg:hidden"><article v-for="c in filtered.filter(c=>['submitted','processing','supplement'].includes(c.status)).slice(0,8)" :key="c.id" class="panel space-y-3 p-4"><div class="flex flex-wrap items-start justify-between gap-2"><div class="min-w-0"><p class="break-all text-sm font-extrabold text-brand-700">{{c.id}}</p><p class="mt-1 break-words text-sm font-semibold">{{c.procedure_title}}</p><p class="mt-1 text-xs text-muted">{{c.applicant_name}} · {{c.category}}</p></div><StatusPill :status="c.status"/><span v-if="c.due_at&&new Date(c.due_at)<new Date()" class="text-xs font-bold text-rose-600">Quá hạn</span></div><div class="grid grid-cols-2 gap-2 border-t border-slate-100 pt-3 text-xs"><div><p class="text-muted">Ngày tiếp nhận</p><p class="font-semibold">{{c.status==='draft'?'Chưa nộp':date(c.submitted_at)}}</p></div><div><p class="text-muted">Hạn xử lý</p><p class="font-semibold">{{c.status==='draft'?'Chưa tính':date(c.due_at)}}</p></div></div><NuxtLink :to="`/ho-so/${c.id}`" class="btn-outline w-full !text-xs">Xem và xử lý <ArrowRight :size="14"/></NuxtLink></article></div><div class="panel scrollbar-hide hidden max-w-full overflow-x-auto lg:block"><table class="w-full min-w-[720px] text-left text-sm"><thead class="bg-[#edf4fd] text-xs font-bold text-slate-700"><tr><th class="px-4 py-3">Mã hồ sơ</th><th class="px-4 py-3">Thủ tục</th><th class="px-4 py-3">Người nộp</th><th class="px-4 py-3">Trạng thái</th><th class="px-4 py-3">Hạn xử lý</th><th class="px-4 py-3">Thao tác</th></tr></thead><tbody><tr v-for="c in filtered.filter(c=>['submitted','processing','supplement'].includes(c.status)).slice(0,20)" :key="c.id" class="border-t border-slate-100 hover:bg-blue-50/60"><td class="px-4 py-3 font-bold text-brand-700">{{c.id}}</td><td class="px-4 py-3">{{c.procedure_title}}</td><td class="px-4 py-3">{{c.applicant_name}}</td><td class="px-4 py-3"><StatusPill :status="c.status"/><span v-if="c.due_at&&new Date(c.due_at)<new Date()" class="ml-1 text-xs font-bold text-rose-600">Quá hạn</span></td><td class="px-4 py-3 text-xs">{{c.status==='draft'?'Chưa tính':date(c.due_at)}}</td><td class="px-4 py-3"><NuxtLink :to="`/ho-so/${c.id}`" class="btn-outline !px-3 !py-1.5 !text-xs">Xem và xử lý <ArrowRight :size="14"/></NuxtLink></td></tr></tbody></table></div></section>
 <section class="panel p-4"><div class="mb-3 flex flex-wrap items-center justify-between gap-2"><h3 class="section-label !mb-0">⚡ Thao tác nhanh</h3></div><div class="grid grid-cols-3 gap-2 text-center"><NuxtLink v-for="x in [{to:'/ho-so',label:'Xem tất cả hồ sơ',icon:FolderOpen},{to:'/thu-tuc',label:'Danh mục thủ tục',icon:ClipboardList},{to:'/thong-bao',label:'Thông báo',icon:Bell},{to:'/bao-cao',label:'Báo cáo thống kê',icon:BarChart3},{to:'/tai-khoan',label:'Quản lý nhân viên',icon:Users},{to:'/ho-so',label:'Duyệt hồ sơ mới',icon:FilePlus2}]" :key="x.label" :to="x.to" class="flex flex-col items-center gap-2 rounded-xl bg-brand-50 p-3 text-xs font-semibold text-brand-800 transition hover:bg-brand-100"><component :is="x.icon" :size="23"/>{{x.label}}</NuxtLink></div></section></div>
 <p class="text-xs text-muted">Hiển thị {{filtered.length}} hồ sơ (tất cả đơn trong hệ thống).</p></div></template>
